class BankAccount {
    readonly id: number;          // set once in constructor
    private balance: number;      // only this class can access
    protected owner: string;      // this class and subclasses
    public currency: string;      // anyone can access

    constructor(id: number, owner: string, initialBalance: number) {
        this.id = id;
        this.owner = owner;
        this.balance = initialBalance;
        this.currency = 'INR';
    }

    // Public method — part of the API
    deposit(amount: number): void {
        if (amount <= 0) throw new Error('Amount must be positive');
        this.balance += amount;
    }

    withdraw(amount: number): void {
        if (amount > this.balance) throw new Error('Insufficient funds');
        this.balance -= amount;
    }

    getBalance(): number {
        return this.balance;  // controlled access to private field
    }
}

const account = new BankAccount(1, 'Alice', 1000);
account.deposit(500);
account.withdraw(200);
console.log(account.getBalance());  // 1300
