// Parameter property shorthand — same as above but shorter
class Point {
    constructor(
        public readonly x: number,
        public readonly y: number
    ) {}

    distanceTo(other: Point): number {
        return Math.hypot(this.x - other.x, this.y - other.y);
    }
}
const p1 = new Point(0, 0);
const p2 = new Point(3, 4);
console.log(p1.distanceTo(p2));  // 5

// Interface — the contract
interface Serializable {
    serialize(): string;
    toJSON(): object;
}

// Abstract class — partial implementation
abstract class Shape implements Serializable {
    constructor(public readonly color: string) {}

    abstract area(): number;    // subclass MUST implement
    abstract perimeter(): number;

    // Concrete method — available in all subclasses
    describe(): string {
        return `A ${this.color} shape with area ${this.area().toFixed(2)}`;
    }

    serialize(): string {
        return JSON.stringify(this.toJSON());
    }
}

class Circle extends Shape {
    constructor(color: string, public readonly radius: number) {
        super(color);
    }
    area():      number { return Math.PI * this.radius ** 2; }
    perimeter(): number { return 2 * Math.PI * this.radius; }
    toJSON(): object {
        return { type: 'circle', radius: this.radius, color: this.color };
    }
}

class Rectangle extends Shape {
    constructor(
        color: string,
        public readonly width: number,
        public readonly height: number
    ) { super(color); }
    area():      number { return this.width * this.height; }
    perimeter(): number { return 2 * (this.width + this.height); }
    toJSON(): object {
        return { type: 'rectangle', width: this.width, height: this.height, color: this.color };
    }
}

const c = new Circle('red', 5);
const r = new Rectangle('blue', 4, 6);

console.log(c.describe());
console.log(r.describe());
console.log(c.serialize());
